using Fleet.Api.Data;using Fleet.Api.Models;using Fleet.Api.Services;using Microsoft.Data.Sqlite;using Microsoft.EntityFrameworkCore;
namespace Fleet.Tests;
public sealed class AssignmentServiceTests:IAsyncLifetime{readonly SqliteConnection c=new("Data Source=:memory:");FleetDbContext db=null!;AssignmentService service=null!;public async Task InitializeAsync(){await c.OpenAsync();db=new(new DbContextOptionsBuilder<FleetDbContext>().UseSqlite(c).Options);await db.Database.EnsureCreatedAsync();db.Users.Add(new User{Id=1,Username="dispatcher",PasswordHash="x",Role="Dispatcher"});db.Vehicles.Add(new Vehicle{Id=1,PlateNumber="A",MakeModel="Van",Year=2025,Odometer=100});db.Drivers.Add(new Driver{Id=1,FullName="Driver",LicenseNumber="L1",LicenseExpiresOn=DateOnly.FromDateTime(DateTime.UtcNow.AddYears(1))});await db.SaveChangesAsync();service=new(db);}public async Task DisposeAsync(){await db.DisposeAsync();await c.DisposeAsync();}
[Fact]public async Task Assign_ReservesVehicle(){await service.AssignAsync(1,1,DateTime.UtcNow.AddMinutes(1),"Delivery",1);Assert.Equal("Assigned",(await db.Vehicles.FindAsync(1))!.Status);}
[Fact]public async Task Assign_PreventsConcurrentActiveAssignment(){await service.AssignAsync(1,1,DateTime.UtcNow.AddMinutes(1),"A",1);await Assert.ThrowsAsync<InvalidOperationException>(()=>service.AssignAsync(1,1,DateTime.UtcNow.AddMinutes(2),"B",1));}
[Fact]public async Task Complete_ReleasesAndUpdatesOdometer(){var a=await service.AssignAsync(1,1,DateTime.UtcNow.AddMinutes(1),"A",1);await service.CompleteAsync(a.Id,150);var v=await db.Vehicles.FindAsync(1);Assert.Equal("Available",v!.Status);Assert.Equal(150,v.Odometer);}
[Fact]public async Task Complete_PreventsOdometerRollback(){var a=await service.AssignAsync(1,1,DateTime.UtcNow.AddMinutes(1),"A",1);await Assert.ThrowsAsync<ArgumentException>(()=>service.CompleteAsync(a.Id,99));}
}
